```json
{
  "root_causes": [
    {
      "service": "ts-preserve-service",
      "fault_kind": "container_cpu_saturated",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT floor(epoch(time)/60) AS mbin, round(avg(value),3) AS cpu_avg, round(max(value),3) AS cpu_max FROM abnormal_metrics WHERE service_name='ts-preserve-service' AND metric='container.cpu.usage' GROUP BY 1 ORDER BY 1",
          "claim": "Preserve container CPU jumps to about 1.4 cores average and 3.6 peak in the first two minutes, versus about 0.06 normally."
        },
        {
          "kind": "metric",
          "sql": "SELECT p, metric, round(avg(value),4) AS avg_v, round(max(value),4) AS max_v FROM (SELECT 'abn' p, * FROM abnormal_metrics UNION ALL SELECT 'norm', * FROM normal_metrics) WHERE service_name='ts-preserve-service' AND metric IN ('jvm.cpu.recent_utilization','container.cpu.usage') GROUP BY ALL ORDER BY metric, p",
          "claim": "The JVM's own CPU utilisation stays near zero in both periods, so the extra CPU burn is at container level, not inside the JVM."
        },
        {
          "kind": "trace",
          "sql": "WITH c AS (SELECT 'abn' p, trace_id, span_id, service_name caller, CAST(duration AS DOUBLE) cd FROM abnormal_traces WHERE attr_span_kind='Client' AND service_name='ts-preserve-service' UNION ALL SELECT 'norm', trace_id, span_id, service_name, CAST(duration AS DOUBLE) FROM normal_traces WHERE attr_span_kind='Client' AND service_name='ts-preserve-service'), sv AS (SELECT 'abn' p, trace_id, parent_span_id, service_name callee, CAST(duration AS DOUBLE) sd FROM abnormal_traces WHERE attr_span_kind='Server' UNION ALL SELECT 'norm', trace_id, parent_span_id, service_name, CAST(duration AS DOUBLE) FROM normal_traces WHERE attr_span_kind='Server') SELECT c.p, callee, count(*) n, round(approx_quantile((cd-sd)/1e6,0.5),2) gap50, round(approx_quantile((cd-sd)/1e6,0.95),2) gap95 FROM c JOIN sv ON c.p=sv.p AND c.trace_id=sv.trace_id AND c.span_id=sv.parent_span_id GROUP BY ALL ORDER BY callee, c.p",
          "claim": "Preserve's outbound calls to every callee show a much larger client-minus-server gap at p95 (about 4 ms normal to 18-52 ms abnormal), with median gaps unchanged."
        },
        {
          "kind": "trace",
          "sql": "SELECT p, count(*) n, round(approx_quantile(sd/1e6,0.5),1) preserve_srv_p50, round(approx_quantile(sd/1e6,0.95),1) preserve_srv_p95 FROM (SELECT 'abn' p, sv.* FROM (SELECT trace_id, parent_span_id, CAST(duration AS DOUBLE) sd FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Server') sv JOIN (SELECT trace_id, span_id FROM abnormal_traces WHERE service_name='ts-ui-dashboard') u ON sv.trace_id=u.trace_id AND sv.parent_span_id=u.span_id) GROUP BY p",
          "claim": "Preserve server spans called from ts-ui-dashboard: p95 rises from about 536 ms normal to about 2296 ms abnormal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "WITH u AS (SELECT 'abn' p, trace_id, span_id FROM abnormal_traces WHERE service_name='ts-ui-dashboard' UNION ALL SELECT 'norm', trace_id, span_id FROM normal_traces WHERE service_name='ts-ui-dashboard'), sv AS (SELECT 'abn' p, trace_id, parent_span_id, CAST(duration AS DOUBLE) sd FROM abnormal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Server' UNION ALL SELECT 'norm', trace_id, parent_span_id, CAST(duration AS DOUBLE) FROM normal_traces WHERE service_name='ts-preserve-service' AND attr_span_kind='Server') SELECT sv.p, count(*) n, round(approx_quantile(sd/1e6,0.5),1) preserve_srv_p50, round(approx_quantile(sd/1e6,0.95),1) preserve_srv_p95 FROM sv JOIN u ON sv.p=u.p AND sv.trace_id=u.trace_id AND sv.parent_span_id=u.span_id GROUP BY sv.p ORDER BY sv.p",
          "claim": "Slowdown in preserve reaches the user-facing dashboard: preserve calls made from ts-ui-dashboard have p95 rising from about 536 ms to about 2296 ms."
        }
      ]
    }
  ]
}
